function crmTemplates(){if(!crmState.templates)return;const q=crmEl('template-search').value.toLowerCase(),rows=crmState.templates.templates.filter(t=>String(t.name).toLowerCase().includes(q));crmEl('template-list').innerHTML=crmTable(['Mensagem','Código','Tipo','Conteúdo','Atualizada',''],rows.map((t,i)=>'<tr><td class="fw-medium">'+crmEsc(t.name)+'</td><td>'+crmEsc(t.id)+'</td><td>'+crmEsc(t.type)+'</td><td><span class="badge bg-secondary-lt">'+(t.content_available?'Registrado':'Indisponível')+'</span></td><td>'+crmEsc(crmWhen(t.updated_at))+'</td><td><button class="btn btn-outline-primary btn-sm" type="button" data-model-preview="'+i+'"'+(window.ShrigmaCrmModels?.content(t,crmState.brand)?'':' disabled')+'>Ver conteúdo</button></td></tr>'))+(rows.length?'':'<div class="card-body text-secondary">Nenhum modelo corresponde à busca.</div>');crmEl('template-coverage').textContent='Catálogo transacional registrado · '+crmState.templates.templates.length+' de '+crmState.templates.total+' · '+crmWhen(crmState.templates.consultado_em)+' · não comprova compatibilidade com campanha';for(const b of crmEl('template-list').querySelectorAll('[data-model-preview]'))b.onclick=()=>crmState.modelLibrary?.preview(rows[Number(b.dataset.modelPreview)]);}

