const crmAudienceCatalogReady=window.ShrigmaCrmRelease?.audienceCatalog===true; // Retained catalog reader installed; Shopify source freshness remains independent.
const crmAudienceCountReady=window.ShrigmaCrmDrafts?.availability?.audienceCount===true;
function crmProductHeld(rule){return window.ShrigmaCrmRelease?.audienceProducts!==true&&(rule?.field==='purchase.product'||!!rule?.rule&&crmProductHeld(rule.rule)||Array.isArray(rule?.rules)&&rule.rules.some(crmProductHeld));}
function crmCountCell(s){if(!crmAudienceCountReady||crmProductHeld(s.definition?.rule))return '<button class="btn btn-sm btn-outline-secondary" data-audience-count="'+crmEsc(s.id)+'" disabled aria-disabled="true" title="Em breve. A contagem ainda está em homologação.">Contar destinatários <span class="badge bg-secondary-lt ms-2">em breve</span></button>';const c=crmState.audienceCounts[s.id];return c?.busy?'Consultando…':c?.source_confirmed===true?'<strong>'+crmNumber(c.eligible_count)+'</strong><div class="source-line">'+crmEsc(crmWhen(c.checked_at))+'</div>':c?.error?'<span class="badge bg-yellow-lt">Não confirmado</span><div class="source-line">'+crmEsc(c.error)+'</div>':'<button class="btn btn-sm btn-outline-secondary" data-audience-count="'+crmEsc(s.id)+'"'+(s.archived||!s.semantic_context?.current?' disabled title="Conferir a versão e a fonte antes de contar"':'')+'>Contar destinatários</button>';}
async function crmCountAudience(id){if(!crmAudienceCountReady)return;const d=crmState.audiences,s=d?.segments.find(s=>s.id===id),brand=crmState.brand,ticket=crmState.ticket;if(!s||s.archived||crmProductHeld(s.definition?.rule)||!s.semantic_context.current||crmState.audienceCounts[id]?.busy)return;crmState.audienceCounts[id]={busy:true};crmAudiences();try{const c=await crmRead('/api/segments',brand,ticket,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({acao:'segmento_contar',brand,id,expected_version:s.version,expected_catalog_hash:d.catalog.catalog_hash})});if(c.segment_id!==id||c.version!==s.version||typeof c.source_confirmed!=='boolean'||c.source_confirmed&&(!Number.isSafeInteger(c.eligible_count)||c.eligible_count<0))throw Error('CONTRACT');crmState.audienceCounts[id]=c.source_confirmed?c:{error:'Fonte sem contagem confirmada'};}catch(e){if(ticket!==crmState.ticket||brand!==crmState.brand)return;crmState.audienceCounts[id]={error:e.code||'Consulta indisponível'};}if(ticket===crmState.ticket&&brand===crmState.brand)crmAudiences();}
