 crmEl('audience-list').innerHTML=crmTable(['Público','Situação','Versão','Fonte','Destinatários','Atualizado',''],rows.map(s=>'<tr><td class="fw-medium">'+crmEsc(s.name)+'</td><td><span class="badge bg-secondary-lt">'+(s.archived?'Arquivado':'Ativo')+'</span></td><td>'+crmNumber(s.version)+'</td><td><span class="badge bg-'+(s.semantic_context?.current?'green':'yellow')+'-lt">'+(s.semantic_context?.current?'Disponível':'Conferir fonte')+'</span></td><td>'+crmCountCell(s)+'</td><td>'+crmEsc(crmWhen(s.updated_at))+'</td><td><button class="btn btn-sm btn-outline-primary" data-audience-detail="'+crmEsc(s.id)+'">Abrir regras</button></td></tr>'))+(rows.length?'':'<div class="card-body text-secondary">Nenhum público corresponde aos filtros.</div>');
